def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    # The left template is bounded by its first all-background vertical line.
    right = next(c for c in range(1, w) if all(grid[r][c] == bg for r in range(h)))
    out = [row[:right + 1] for row in grid]

    # Horizontal background rows separate the template into slots.
    separators = [r for r in range(h) if all(grid[r][c] == bg for c in range(right + 1))]
    slots = [(a + 1, b) for a, b in zip(separators, separators[1:]) if b > a + 1]

    # Find connected components of colored cells outside the template.
    seen = set()
    components = []
    for r in range(h):
        for c in range(right + 1, w):
            color = grid[r][c]
            if color == 0 or color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and right < nx < w and
                        grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((color, cells))

    # Match each slot's zero-cell pattern to a translated colored component.
    patterns = []
    for top, bottom in slots:
        holes = {(r - top, c) for r in range(top, bottom)
                 for c in range(1, right) if grid[r][c] == 0}
        patterns.append((bottom - top, holes))

    def fits(slot, component):
        height, holes = slot
        color, cells = component
        minr = min(r for r, c in cells)
        minc = min(c for r, c in cells)
        shape = {(r - minr, c - minc) for r, c in cells}
        for dr in range(height):
            for dc in range(1, right):
                shifted = {(r + dr, c + dc) for r, c in shape}
                if shifted == holes:
                    return color
        return None

    used = set()

    def assign(i):
        if i == len(patterns):
            return True
        for j, component in enumerate(components):
            if j in used:
                continue
            color = fits(patterns[i], component)
            if color is not None:
                used.add(j)
                top, bottom = slots[i]
                for r in range(top, bottom):
                    for c in range(1, right):
                        if grid[r][c] == 0:
                            out[r][c] = color
                if assign(i + 1):
                    return True
                for r in range(top, bottom):
                    for c in range(1, right):
                        if grid[r][c] == 0:
                            out[r][c] = 0
                used.remove(j)
        return False

    assign(0)
    return out
